export interface SearchPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  currentPath: string;
  query: string;
  onQueryChange: (value: string) => void;
  anchorRef: React.RefObject<HTMLElement | null>;
}

interface FlatItem {
  id: string;
  type: 'row' | 'group-header';
  groupKey?: ResultGroupKey;
  run: () => void;
}

type ResultKind = PaletteResultKind;

const resultTypeLabel: Record<ResultKind, string> = {
  playbook: 'Playbook',
  action: 'Action',
  service: 'Landing page',
  page: 'Page',
  documentation: 'Documentation',
  cluster: 'Cluster',
  host: 'Host',
  system: 'System',
  group: 'Group',
  workspace: 'Workspace',
  role: 'Role',
  support: 'Support',
  suggestion: 'Suggestion',
};

type ResultGroupKey =
  | 'services'
  | 'inventories'
  | 'learning'
  | 'playbooks';

const resultGroupLabel: Record<ResultGroupKey, string> = {
  services: 'Services & pages',
  inventories: 'Inventories',
  learning: 'Learning resources',
  playbooks: 'Playbooks & actions',
};

const resultGroupOrder: ResultGroupKey[] = ['services', 'inventories', 'learning', 'playbooks'];

const kindToGroup = (kind: ResultKind): ResultGroupKey => {
  switch (kind) {
    case 'service':
    case 'page':
      return 'services';
    case 'cluster':
    case 'host':
    case 'system':
    case 'group':
    case 'workspace':
    case 'role':
    case 'support':
      return 'inventories';
    case 'documentation':
      return 'learning';
    case 'playbook':
    case 'action':
    case 'suggestion':
      return 'playbooks';
    default:
      return 'services';
  }
};

const resultTypeIcon: Record<ResultKind, React.ReactNode> = {
  playbook: <PlayIcon />,
  action: <TerminalIcon />,
  service: <HomeIcon />,
  page: <ListIcon />,
  documentation: <BookOpenIcon />,
  cluster: <ClusterIcon />,
  host: <ServerIcon />,
  system: <HddIcon />,
  group: <LayerGroupIcon />,
  workspace: <FolderOpenIcon />,
  role: <ShieldAltIcon />,
  support: <HeadsetIcon />,
  suggestion: <SearchIcon />,
};

const MAX_HISTORY = 10;

const SEED_RECENT_POOL: PaletteAction[] = [
  { id: 'seed-cluster', title: 'cluster-prod-openshift-01', meta: 'OpenShift 4.16 · Healthy', status: 'success', kind: 'cluster', nav: { route: '/overview', filters: ['Cluster: cluster-prod-openshift-01'] } },
  { id: 'seed-host', title: 'prod-cluster-01', meta: 'RHEL 9.4 · 2 Critical · 2,854 Advisories', status: 'danger', kind: 'host', nav: { route: '/vulnerability/systems/prod-cluster-01' } },
  { id: 'seed-group', title: 'rhel-prod-host-group', meta: 'RHEL · 48 systems', kind: 'group', nav: { route: '/overview', filters: ['Group: rhel-prod-host-group'] } },
  { id: 'seed-workspace', title: 'production', meta: 'Workspace · 12 members', kind: 'workspace', nav: { route: '/workspaces/production' } },
  { id: 'seed-role', title: 'Organization Administrator', meta: 'Role · 22 permissions', kind: 'role', nav: { route: '/roles/org-admin' } },
  { id: 'seed-support', title: 'Case #03519874', meta: 'Waiting on Red Hat · High severity', status: 'warning', kind: 'support', nav: { route: '/support/case/03519874' } },
  { id: 'seed-alerts', title: 'Alert Manager', meta: 'View and manage alerts', kind: 'action', nav: { route: '/alert-manager' } },
  { id: 'seed-subs', title: 'Subscription usage', meta: 'RHEL · 142 of 200 used', kind: 'action', nav: { route: '/overview', filters: ['Subscriptions', 'RHEL usage'] } },
  { id: 'seed-users', title: 'Users', meta: 'Identity & Access Management', kind: 'page', nav: { route: '/users' } },
  { id: 'seed-insights', title: 'Red Hat Insights', meta: 'Advisor recommendations', kind: 'service', nav: { route: '/overview', filters: ['Insights'] } },
  { id: 'seed-learning', title: 'Learning Resources', meta: 'Tutorials and documentation', kind: 'page', nav: { route: '/learning-resources' } },
  { id: 'seed-groups', title: 'cloud-operators', meta: 'Group · 6 members · 3 roles', kind: 'group', nav: { route: '/groups/cloud-operators' } },
];

function pickRandom<T>(arr: T[], n: number): T[] {
  const shuffled = [...arr].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, n);
}

let sessionHistory: PaletteAction[] = pickRandom(SEED_RECENT_POOL, 6).map((item) => ({
  ...item,
  id: `history-${item.id}`,
}));
let historyListeners: Array<() => void> = [];

const addToHistory = (item: PaletteAction) => {
  const entry: PaletteAction = {
    ...item,
    id: `history-${item.id}`,
  };
  sessionHistory = [entry, ...sessionHistory.filter((h) => h.id !== entry.id)].slice(0, MAX_HISTORY);
  historyListeners.forEach((fn) => fn());
};

const useSessionHistory = (): PaletteAction[] => {
  const [, forceUpdate] = React.useReducer((x: number) => x + 1, 0);
  React.useEffect(() => {
    historyListeners.push(forceUpdate);
    return () => {
      historyListeners = historyListeners.filter((fn) => fn !== forceUpdate);
    };
  }, []);
  return sessionHistory;
};

const kindForItem = (item: PaletteAction): ResultKind => {
  if (item.kind) {
    return item.kind;
  }
  if (item.playbook) {
    return 'playbook';
  }
  return 'action';
};

const entityKind = (item: PaletteAction): ResultKind => {
  if (item.kind) {
    return item.kind;
  }
  const title = item.title.toLowerCase();
  if (title.includes('cluster')) {
    return 'cluster';
  }
  if (title.includes('group')) {
    return 'group';
  }
  if (title.includes('system')) {
    return 'system';
  }
  return 'host';
};

const SearchPalette: React.FunctionComponent<SearchPaletteProps> = ({
  isOpen,
  onClose,
  currentPath,
  query,
  onQueryChange,
  anchorRef,
}) => {
  const navigate = useNavigate();
  const panelRef = React.useRef<HTMLDivElement>(null);
  const [selectedIndex, setSelectedIndex] = React.useState(0);
  const [playbookMessage, setPlaybookMessage] = React.useState<string | null>(null);
  const [panelStyle, setPanelStyle] = React.useState<React.CSSProperties>({});
  const [selectedServiceId, setSelectedServiceId] = React.useState(DEFAULT_SERVICE_ID);
  const [favoritedItems, setFavoritedItems] = React.useState<Set<string>>(new Set());
  const [collapsedGroups, setCollapsedGroups] = React.useState<Set<ResultGroupKey>>(new Set());
  const recentEntities = useSessionHistory();
  const selectedService = getSelectedService(selectedServiceId);
  const showSearchShortcuts = selectedServiceId === DEFAULT_SERVICE_ID && favoritedItems.size === 0;

  const toggleGroup = React.useCallback((key: ResultGroupKey) => {
    setCollapsedGroups((current) => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }, []);

  const toggleFavorite = React.useCallback((id: string) => {
    setFavoritedItems((current) => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const hasQuery = query.trim().length > 0;
  const resolution = React.useMemo(() => resolveQuery(query), [query]);
  const commonActions = React.useMemo(() => getCommonActions(currentPath), [currentPath]);
  const suggestions = React.useMemo(() => getContextualSuggestions(currentPath), [currentPath]);
  const matchingPrefixes = React.useMemo(() => getMatchingPrefixes(query), [query]);
  const hasResults = Boolean(
    resolution.answer ||
      resolution.actions.length ||
      resolution.entities.length ||
      resolution.docs.length,
  );

  const closeAndReset = React.useCallback(() => {
    setSelectedIndex(0);
    setPlaybookMessage(null);
    setSelectedServiceId(DEFAULT_SERVICE_ID);
    onClose();
  }, [onClose]);

  const goTo = React.useCallback(
    (nav?: SearchNavTarget) => {
      if (!nav) {
        return;
      }
      closeAndReset();
      navigate(nav.route, {
        state: nav.filters || nav.query ? { searchFilters: nav.filters, searchQuery: nav.query } : undefined,
      });
    },
    [closeAndReset, navigate],
  );

  const runPlaybook = React.useCallback(() => {
    setPlaybookMessage('Remediation playbook queued for Ansible Automation Platform (prototype).');
  }, []);

  const applyQuery = React.useCallback(
    (nextQuery: string) => {
      onQueryChange(nextQuery);
      setSelectedIndex(0);
      setPlaybookMessage(null);
    },
    [onQueryChange],
  );

  const runAction = React.useCallback(
    (action: PaletteAction) => {
      const rawId = action.id.replace(/^(history-|top-)/, '');
      if (rawId === 'ai-guidance') {
        addToHistory(action);
        applyQuery('Which OpenShift clusters are running out of storage?');
        return;
      }
      if (rawId === 'ctx-home-cve' || rawId === 'ctx-cves') {
        addToHistory(action);
        applyQuery('Show me all RHEL 8 servers with critical CVEs in production');
        return;
      }
      if (rawId === 'ctx-home-storage') {
        addToHistory(action);
        applyQuery('Which OpenShift clusters are running out of storage?');
        return;
      }
      if (rawId === 'ctx-patch') {
        addToHistory(action);
        applyQuery('Generate patch status report');
        return;
      }
      if (action.access === 'restricted') {
        addToHistory(action);
        goTo(action.requestAccess);
        return;
      }
      if (action.playbook) {
        addToHistory(action);
        runPlaybook();
        return;
      }
      if (action.nav) {
        addToHistory(action);
        goTo(action.nav);
      }
    },
    [applyQuery, goTo, runPlaybook],
  );

  const resultGroups = React.useMemo(() => {
    if (!hasQuery) return [];

    const taggedRows: { item: PaletteAction; kind: ResultKind }[] = [
      ...resolution.actions.map((item) => ({ item, kind: kindForItem(item) })),
      ...resolution.entities.map((item) => ({ item, kind: entityKind(item) })),
      ...resolution.docs.map((item) => ({ item, kind: (item.kind || 'documentation') as ResultKind })),
    ];

    const groups: Record<ResultGroupKey, { item: PaletteAction; kind: ResultKind }[]> = {
      services: [],
      inventories: [],
      learning: [],
      playbooks: [],
    };

    taggedRows.forEach((row) => {
      groups[kindToGroup(row.kind)].push(row);
    });

    return resultGroupOrder
      .filter((key) => groups[key].length > 0)
      .map((key) => ({ key, label: resultGroupLabel[key], rows: groups[key] }));
  }, [hasQuery, resolution]);

  const topResults = React.useMemo(() => {
    if (!hasQuery) return [];
    const top: { item: PaletteAction; kind: ResultKind }[] = [];
    const seen = new Set<string>();
    const MAX_TOP = 5;

    const addIfNew = (item: PaletteAction, kind: ResultKind) => {
      if (!seen.has(item.id) && top.length < MAX_TOP) {
        seen.add(item.id);
        top.push({ item, kind });
      }
    };

    const queryLower = query.toLowerCase();
    const entityKinds = resolution.entities.map((item) => ({ item, kind: entityKind(item) }));
    const dominantKind = entityKinds.length > 0
      ? entityKinds.reduce<Record<string, number>>((acc, { kind }) => { acc[kind] = (acc[kind] || 0) + 1; return acc; }, {})
      : {};
    const topEntityKind = Object.entries(dominantKind).sort((a, b) => b[1] - a[1])[0]?.[0] as ResultKind | undefined;

    const normalizeMatch = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    const queryNorm = normalizeMatch(queryLower);
    const firstEntityMatchesQuery = resolution.entities.length > 0 &&
      normalizeMatch(resolution.entities[0].title).includes(queryNorm);
    const isEntityFocused = !resolution.answer && (firstEntityMatchesQuery || (topEntityKind && (
      queryLower.includes(topEntityKind) ||
      (dominantKind[topEntityKind] || 0) >= 3
    )));

    if (resolution.answer) {
      resolution.actions.forEach((item) => addIfNew(item, kindForItem(item)));
      resolution.entities.forEach((item) => addIfNew(item, entityKind(item)));
      resolution.docs.forEach((item) => addIfNew(item, (item.kind || 'documentation') as ResultKind));
    } else if (isEntityFocused) {
      entityKinds
        .filter(({ kind }) => kind === topEntityKind)
        .forEach(({ item, kind }) => addIfNew(item, kind));
      resolution.actions.forEach((item) => addIfNew(item, kindForItem(item)));
      entityKinds
        .filter(({ kind }) => kind !== topEntityKind)
        .forEach(({ item, kind }) => addIfNew(item, kind));
    } else {
      resolution.actions.forEach((item) => {
        const kind = kindForItem(item);
        if (kind === 'service') addIfNew(item, kind);
      });
      if (resolution.entities.length > 0) {
        const item = resolution.entities[0];
        addIfNew(item, entityKind(item));
      }
      if (resolution.docs.length > 0) {
        const item = resolution.docs[0];
        addIfNew(item, (item.kind || 'documentation') as ResultKind);
      }
      resolution.actions.forEach((item) => {
        const kind = kindForItem(item);
        if (kind !== 'service') addIfNew(item, kind);
      });
      resolution.entities.slice(1).forEach((item) => {
        addIfNew(item, entityKind(item));
      });
    }

    return top;
  }, [hasQuery, query, resolution]);

  const flatItems = React.useMemo((): FlatItem[] => {
    const items: FlatItem[] = [];

    if (!hasQuery) {
      if (showSearchShortcuts) {
        recentEntities.forEach((item) => items.push({ id: item.id, type: 'row', run: () => runAction(item) }));
        commonActions.forEach((item) => items.push({ id: item.id, type: 'row', run: () => runAction(item) }));
        suggestions.forEach((item) => items.push({ id: item.id, type: 'row', run: () => runAction(item) }));
      }
      return items;
    }

    topResults.forEach(({ item }) => items.push({ id: `top-${item.id}`, type: 'row', run: () => runAction(item) }));

    resultGroups.forEach((group) => {
      items.push({
        id: `group-header-${group.key}`,
        type: 'group-header',
        groupKey: group.key,
        run: () => toggleGroup(group.key),
      });
      if (!collapsedGroups.has(group.key)) {
        group.rows.forEach(({ item }) => items.push({ id: item.id, type: 'row', run: () => runAction(item) }));
      }
    });

    return items;
  }, [hasQuery, resolution, runAction, runPlaybook, goTo, suggestions, showSearchShortcuts, resultGroups, collapsedGroups, toggleGroup, topResults]);

  React.useEffect(() => {
    setSelectedIndex(0);
    setCollapsedGroups(new Set());
  }, [query, isOpen, selectedServiceId]);

  React.useEffect(() => {
    if (!isOpen || hasQuery) {
      setSelectedServiceId(DEFAULT_SERVICE_ID);
    }
  }, [isOpen, hasQuery]);

  React.useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const updatePosition = () => {
      const anchor = anchorRef.current;
      if (!anchor) {
        return;
      }
      const rect = anchor.getBoundingClientRect();
      setPanelStyle({
        top: rect.bottom - 1,
        left: rect.left,
        width: rect.width,
        ['--ai-search-palette--InsetBlockStart' as string]: `${rect.bottom - 1}px`,
      });
    };

    updatePosition();
    window.addEventListener('resize', updatePosition);
    window.addEventListener('scroll', updatePosition, true);
    return () => {
      window.removeEventListener('resize', updatePosition);
      window.removeEventListener('scroll', updatePosition, true);
    };
  }, [isOpen, query, anchorRef]);

  React.useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      const isInputField = target?.tagName === 'INPUT' || target?.tagName === 'TEXTAREA';

      if (event.key === 'Enter' && isInputField && hasQuery) {
        event.preventDefault();
        event.stopPropagation();
        addToHistory({
          id: `search-${query.trim()}`,
          title: query.trim(),
          meta: 'Search query',
          kind: 'suggestion',
          nav: { route: `/search?q=${encodeURIComponent(query.trim())}` },
        });
        closeAndReset();
        navigate(`/search?q=${encodeURIComponent(query.trim())}`);
        return;
      }

      const isNestedControl = Boolean(
        target?.closest(
          '.ai-search-palette__feedback, .ai-search-palette__item-access, .ai-search-palette__services, .ai-search-palette__service-detail',
        ),
      );

      if (event.key === 'Escape') {
        event.preventDefault();
        closeAndReset();
        return;
      }
      if (isNestedControl) {
        return;
      }
      if (event.key === 'ArrowDown') {
        event.preventDefault();
        setSelectedIndex((current) => (flatItems.length === 0 ? 0 : (current + 1) % flatItems.length));
        return;
      }
      if (event.key === 'ArrowUp') {
        event.preventDefault();
        setSelectedIndex((current) =>
          flatItems.length === 0 ? 0 : (current - 1 + flatItems.length) % flatItems.length,
        );
        return;
      }
      if (event.key === 'ArrowLeft') {
        const selected = flatItems[selectedIndex];
        if (selected?.type === 'group-header' && selected.groupKey && !collapsedGroups.has(selected.groupKey)) {
          event.preventDefault();
          toggleGroup(selected.groupKey);
        }
        return;
      }
      if (event.key === 'ArrowRight') {
        const selected = flatItems[selectedIndex];
        if (selected?.type === 'group-header' && selected.groupKey && collapsedGroups.has(selected.groupKey)) {
          event.preventDefault();
          toggleGroup(selected.groupKey);
        }
        return;
      }
      if (event.key === ' ' && !isInputField) {
        const selected = flatItems[selectedIndex];
        if (selected?.type === 'group-header') {
          event.preventDefault();
          selected.run();
        }
        return;
      }
      if (event.key === 'Enter') {
        const selected = flatItems[selectedIndex];
        if (selected) {
          event.preventDefault();
          selected.run();
        }
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [isOpen, flatItems, selectedIndex, closeAndReset]);

  React.useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const onPointerDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (anchorRef.current?.contains(target) || panelRef.current?.contains(target)) {
        return;
      }
      const el = target instanceof Element ? target : (target as Node).parentElement;
      if (el?.closest('.feedback-overlay.is-active, .feedback-pin-form, .feedback-pin-marker, .feedback-topbar, .feedback-sidebar')) {
        return;
      }
      closeAndReset();
    };

    document.addEventListener('mousedown', onPointerDown);
    return () => document.removeEventListener('mousedown', onPointerDown);
  }, [isOpen, anchorRef, closeAndReset]);

  const isActive = (id: string) => flatItems[selectedIndex]?.id === id;

  const renderRow = (item: PaletteAction, kind: ResultKind) => {
    const isRestricted = item.access === 'restricted';
    const RowTag = isRestricted ? 'div' : 'button';

    return (
      <RowTag
        {...(!isRestricted ? { type: 'button' as const } : {})}
        key={item.id}
        id={`ai-search-item-${item.id}`}
        className={`ai-search-palette__item${isActive(item.id) ? ' is-active' : ''}${
          isRestricted ? ' is-restricted' : ''
        }`}
        role="option"
        aria-selected={isActive(item.id)}
        aria-label={
          isRestricted
            ? `${item.title}, access required, owned by ${item.owner || 'unknown'}`
            : undefined
        }
        onMouseEnter={() => {
          const index = flatItems.findIndex((flat) => flat.id === item.id);
          if (index >= 0) {
            setSelectedIndex(index);
          }
        }}
        onClick={() => runAction(item)}
      >
        <Tooltip
          content={isRestricted ? `${resultTypeLabel[kind]} · Access required` : resultTypeLabel[kind]}
          position="left"
        >
          <span
            className="ai-search-palette__type"
            aria-label={isRestricted ? `${resultTypeLabel[kind]}, access required` : resultTypeLabel[kind]}
          >
            <Icon {...(isRestricted ? { status: 'warning' as const } : {})}>
              {isRestricted ? <LockIcon /> : resultTypeIcon[kind]}
            </Icon>
          </span>
        </Tooltip>
        <span className="ai-search-palette__item-body">
          <span className="ai-search-palette__item-title">{item.title}</span>
          {(item.description || item.meta) && (
            <span className="ai-search-palette__item-meta">{item.meta || item.description}</span>
          )}
          {isRestricted && item.owner && (
            <span className="ai-search-palette__item-meta">Owner: {item.owner}</span>
          )}
        </span>
        {isRestricted && (
          <span className="ai-search-palette__item-access">
            <Label status="warning" isCompact>
              Access required
            </Label>
            <Button
              variant="link"
              isInline
              size="sm"
              onClick={(event) => {
                event.stopPropagation();
                goTo(item.requestAccess);
              }}
            >
              Request access
            </Button>
          </span>
        )}
      </RowTag>
    );
  };

  const sectionTitle = (text: string) => (
    <Title headingLevel="h3" size="md" className="ai-search-palette__section-title">
      {text}
    </Title>
  );

  if (!isOpen) {
    return null;
  }

  return (
    <>
      <div className="ai-search-palette__backdrop" />
      <div ref={panelRef} className="ai-search-palette__panel" style={panelStyle}>
      <Card
        className={`ai-search-palette__dropdown${!hasQuery ? ' is-zero-state' : ''}`}
        isCompact
        role="dialog"
        aria-label="Search results"
      >
        {hasQuery && resultGroups.length > 0 && (
          <div className="ai-search-palette__results-summary">
            <span className="ai-search-palette__results-summary-label">Results</span>
            {resultGroups.map((group) => (
              <Button
                key={group.key}
                variant="plain"
                isInline
                size="sm"
                className="ai-search-palette__results-summary-chip"
                onClick={() => {
                  if (collapsedGroups.has(group.key)) {
                    toggleGroup(group.key);
                  }
                  requestAnimationFrame(() => {
                    const el = document.getElementById(`ai-search-item-group-header-${group.key}`);
                    const scrollParent = el?.closest('.ai-search-palette__body');
                    if (el && scrollParent) {
                      const parentRect = scrollParent.getBoundingClientRect();
                      const elRect = el.getBoundingClientRect();
                      const offset = elRect.top - parentRect.top + scrollParent.scrollTop;
                      scrollParent.scrollTo({ top: offset, behavior: 'smooth' });
                    }
                  });
                }}
              >
                {group.label}
                <Label isCompact>{group.rows.length}</Label>
              </Button>
            ))}
          </div>
        )}
        <CardBody className="ai-search-palette__body">
          {playbookMessage && (
            <Flex>
              <FlexItem>
                <Alert variant="success" isInline title="Playbook generated">
                  {playbookMessage}
                </Alert>
              </FlexItem>
            </Flex>
          )}

          {!hasQuery && (
            <Split className="ai-search-palette__zero-state">
              <SplitItem className="ai-search-palette__services">
                <SearchServicesPanel
                  selectedItemId={selectedServiceId}
                  onSelectService={setSelectedServiceId}
                  onNavigate={goTo}
                />
              </SplitItem>
              <SplitItem isFilled className="ai-search-palette__zero-results">
                {selectedService && !showSearchShortcuts ? (
                  <div className="ai-search-palette__service-detail">
                    <SearchServiceDetail
                      item={selectedService}
                      favoritedItems={favoritedItems}
                      onToggleFavorite={toggleFavorite}
                      onNavigate={goTo}
                    />
                  </div>
                ) : (
                  <div role="listbox" aria-label="Search suggestions">
                    {recentEntities.length > 0 && (
                      <>
                        {sectionTitle('Recent')}
                        <div className="ai-search-palette__two-col">
                          {recentEntities.map((item) => (
                            <div key={item.id} className="ai-search-palette__two-col-item">
                              {renderRow(item, entityKind(item))}
                            </div>
                          ))}
                        </div>
                      </>
                    )}

                    <div className="ai-search-palette__two-col">
                      <div className="ai-search-palette__two-col-item">
                        {sectionTitle('Common actions')}
                        {commonActions.map((item) => renderRow(item, kindForItem(item)))}
                      </div>
                      <div className="ai-search-palette__two-col-item">
                        {sectionTitle('Suggestions')}
                        {suggestions.map((item) => renderRow(item, 'suggestion'))}
                      </div>
                    </div>

                    {sectionTitle('Prefixed search')}
                    <div className="ai-search-palette__prefix-hints">
                      {searchPrefixes.map((p) => (
                        <button
                          key={p.key}
                          type="button"
                          className="ai-search-palette__prefix-chip"
                          onClick={() => {
                            if (onQueryChange) {
                              onQueryChange(p.label);
                            }
                          }}
                        >
                          <Label isCompact color="blue">{p.label}</Label>
                          <span>{p.description}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </SplitItem>
            </Split>
          )}

          {hasQuery && matchingPrefixes.length > 0 && !resolution.prefix && (
            <div className="ai-search-palette__prefix-suggestions">
              <span className="ai-search-palette__prefix-suggestions-label">Filter by type</span>
              <div className="ai-search-palette__prefix-suggestions-row">
                {matchingPrefixes.map((p) => (
                  <button
                    key={p.key}
                    type="button"
                    className="ai-search-palette__prefix-chip"
                    onClick={() => onQueryChange(p.label)}
                  >
                    <Label isCompact color="blue">{p.label}</Label>
                    <span>{p.description}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {hasQuery && (
          <div role="listbox" aria-label="Search results">
            {resolution.prefix && (
              <div className="ai-search-palette__prefix-active">
                <Label color="blue" isCompact>{resolution.prefix.label}</Label>
                <span>{resolution.prefix.description}</span>
                <Button
                  variant="plain"
                  isInline
                  size="sm"
                  onClick={() => {
                    const parsed = parseQuery(query);
                    onQueryChange(parsed.term || '');
                  }}
                  style={{ marginInlineStart: 'auto', fontSize: 'var(--pf-t--global--font--size--body--sm)' }}
                >
                  Clear filter
                </Button>
              </div>
            )}

            {resolution.answer && !resolution.prefix && (
              <div className="ai-search-palette__ai-hint">
                <img src={SparkleIcon} alt="" width={14} height={14} />
                <Content component="small">
                  AI answer available — press Enter to view full results
                </Content>
              </div>
            )}

            {!hasResults && (
              <Content className="ai-search-palette__empty">
                <p>No matching results. Try another query, or tell us what you expected below.</p>
              </Content>
            )}

            {topResults.length > 0 && (
              <>
                {sectionTitle('Top results')}
                {topResults.map(({ item, kind }) => renderRow(item, kind))}
              </>
            )}

            {resultGroups.map((group) => {
              const isCollapsed = collapsedGroups.has(group.key);
              const headerId = `group-header-${group.key}`;
              return (
                <React.Fragment key={group.key}>
                  <button
                    type="button"
                    id={`ai-search-item-${headerId}`}
                    className={`ai-search-palette__group-header${isActive(headerId) ? ' is-active' : ''}`}
                    aria-expanded={!isCollapsed}
                    onClick={() => toggleGroup(group.key)}
                    onMouseEnter={() => {
                      const index = flatItems.findIndex((flat) => flat.id === headerId);
                      if (index >= 0) setSelectedIndex(index);
                    }}
                  >
                    <Icon size="sm">
                      {isCollapsed ? <AngleRightIcon /> : <AngleDownIcon />}
                    </Icon>
                    <span className="ai-search-palette__group-header-text">
                      {group.label} ({group.rows.length})
                    </span>
                  </button>
                  {!isCollapsed && group.rows.map(({ item, kind }) => renderRow(item, kind))}
                </React.Fragment>
              );
            })}
          </div>
          )}
        </CardBody>
        <CardFooter>
          {hasQuery && <SearchFeedback query={query.trim()} />}
          {!hasQuery && <Divider />}
          <div className="ai-search-palette__footer">
            <span>
              <span className="ai-search-palette__kbd">↑↓</span> Navigate
            </span>
            <span>
              <span className="ai-search-palette__kbd">Enter</span> Execute
            </span>
            <span>
              <span className="ai-search-palette__kbd">Esc</span> Close
            </span>
            <span>
              <span className="ai-search-palette__kbd">{getShortcutLabel()}</span> Open
            </span>
          </div>
        </CardFooter>
      </Card>
      </div>
    </>
  );
};

export { SearchPalette };

